import random
import struct

# Generator for an arbitrary byte buffer tailored to exercise dkhash_insert and iocache/fanout paths.
# Compose multiple segments: ASCII, UTF-8, NUL-rich, delimiter-rich, patterns, random bytes.
# Size limited to <= 4096 bytes.

def _rand_ascii(rng, min_len, max_len):
    n = rng.randint(min_len, max_len)
    alphabet = (
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789-_:.@/"
    )
    # Build a bytes object directly
    return (''.join(rng.choice(alphabet) for _ in range(n))).encode('ascii')


def _rand_utf8(rng, min_len, max_len):
    n = rng.randint(min_len, max_len)
    out = bytearray()
    while len(out) < n:
        choice = rng.random()
        try:
            if choice < 0.7:
                out.append(rng.randint(0x20, 0x7e))
            elif choice < 0.85:
                cp = rng.randint(0x80, 0x7FF)
                out.extend(chr(cp).encode('utf-8'))
            elif choice < 0.95:
                cp = rng.randint(0x800, 0xFFFF)
                out.extend(chr(cp).encode('utf-8'))
            else:
                cp = rng.randint(0x10000, 0x10FFFF)
                out.extend(chr(cp).encode('utf-8'))
        except Exception:
            # Fallback to ASCII char on encoding issues
            out.append(rng.randint(0x20, 0x7e))
        if len(out) > n:
            break
    return bytes(out[:n])


def _repeated_pattern(pattern: bytes, total_len: int) -> bytes:
    if not pattern:
        return b""
    reps = (total_len + len(pattern) - 1) // len(pattern)
    return (pattern * reps)[:total_len]


def _inc_bytes(start, length):
    return bytes(((start + i) & 0xff) for i in range(length))


def _random_bytes(rng, n):
    return bytes(rng.getrandbits(8) for _ in range(n))


def _pack_u32_le(n):
    return struct.pack('<I', n & 0xFFFFFFFF)


def _kv_like_pairs(rng, count):
    # Build lines like key=value\n with varied chars and possible empty values
    out = bytearray()
    for _ in range(count):
        k = _rand_ascii(rng, 3, 16)
        v_choice = rng.random()
        if v_choice < 0.4:
            v = _rand_ascii(rng, 0, 24)
        elif v_choice < 0.8:
            v = _rand_utf8(rng, 0, 24)
        else:
            v = _random_bytes(rng, rng.randint(0, 24))
        out.extend(k)
        out.extend(b"=")
        out.extend(v)
        out.extend(b"\n")
    return bytes(out)


def _delim_rich_blocks(rng):
    blocks = []
    delims = [b"\n", b"\r\n", b"\0", b"::", b"|", b",", b"\t"]
    for d in delims:
        blocks.append(_repeated_pattern(d, rng.randint(1, 16)))
        blocks.append(_rand_ascii(rng, 2, 8) + d + _rand_ascii(rng, 2, 8))
    return b"".join(blocks)


def _host_service_pairs(rng, n):
    # Useful for dkhash dual keys
    hosts = [
        b"localhost", b"example.com", b"srv-01", b"db01", b"web-frontend",
        b"2001:db8::1", b"host_with_underscores", b"xn--fiqs8s"
    ]
    svcs = [
        b"PING", b"HTTP", b"CPU Load", b"Disk_/var", b"Memory", b"SSH",
        b"Service:With:Colons", b"weird\0service"
    ]
    out = bytearray()
    for _ in range(n):
        h = rng.choice(hosts)
        s = rng.choice(svcs)
        out.extend(h + b"\0" + s + b"\0")
        out.extend(h + b"\n" + s + b"\n")
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    segments = []

    # Segment 1: ASCII keys and values
    segments.append(_kv_like_pairs(rng, rng.randint(5, 20)))

    # Segment 2: Host/Service combined pieces
    segments.append(_host_service_pairs(rng, rng.randint(2, 6)))

    # Segment 3: Random payloads
    for _ in range(rng.randint(3, 6)):
        choice = rng.random()
        if choice < 0.25:
            segments.append(_random_bytes(rng, rng.randint(16, 128)))
        elif choice < 0.5:
            segments.append(_rand_ascii(rng, 16, 128))
        elif choice < 0.75:
            segments.append(_rand_utf8(rng, 16, 128))
        else:
            segments.append(_inc_bytes(rng.randint(0, 255), rng.randint(16, 128)))

    # Segment 4: Delimiter-rich blocks for iocache_use_delim
    segments.append(_delim_rich_blocks(rng))

    # Segment 5: Repeated patterns
    patterns = [b"A", b"AB", b"\x00\xff", b"\r\n", b"::", b"key:value|"]
    for p in patterns:
        segments.append(_repeated_pattern(p, rng.randint(8, 64)))

    # Segment 6: Length-prefixed random chunks
    for _ in range(rng.randint(2, 5)):
        chunk = _random_bytes(rng, rng.randint(8, 96))
        segments.append(_pack_u32_le(len(chunk)))
        segments.append(chunk)

    # Segment 7: Ensure NULs appear
    nul_mix = [b"\0", b"\0\0", b"text\0more", b"\0end"]
    rng.shuffle(nul_mix)
    segments.extend(nul_mix)

    # Segment 8: Small and medium blobs for fanout data copies
    for _ in range(rng.randint(2, 4)):
        n = rng.randint(1, 512)
        blob = _random_bytes(rng, n)
        segments.append(blob)

    # Segment 9: Command-like strings
    cmds = [
        b"/bin/true\n", b"echo hello world\n", b"/usr/bin/env -i KEY=VALUE\n",
        b"printf:%d,%s\n", b"SELECT * FROM t WHERE id=42;\n",
    ]
    rng.shuffle(cmds)
    segments.extend(cmds)

    # Stitch together up to 4096 bytes
    out = bytearray()
    for seg in segments:
        if len(out) + len(seg) > 4096:
            seg = seg[: max(0, 4096 - len(out))]
        out.extend(seg)
        if len(out) >= 4096:
            break

    # Guarantee non-empty output and include at least one newline and one NUL
    if not out:
        out.extend(b"\0\n")
    if b"\n" not in out and len(out) < 4096:
        out.extend(b"\n")
    if b"\0" not in out and len(out) < 4096:
        out.extend(b"\0")

    return bytes(out)

import os
import random
import string
from typing import List

# Data type: filesystem path
# We generate valid NUL-terminated (by C conventions) byte buffers representing
# filesystem paths. These are used by fuzz stubs that request FUZZ_PARAM_STR
# and FUZZ_PARAM_FILENAME. The harness will map our bytes to those parameters.
#
# Goals:
# - Provide absolute and relative paths
# - Include ., .. segments, repeated slashes
# - Include safe characters commonly used in file names
# - Keep under 4096 bytes
# - Sometimes produce socket-friendly short paths (<= 108 bytes typical sun_path)
# - Sometimes include trailing slash, empty components, or edge forms like "/", ".", ".."

SAFE_CHARS = string.ascii_letters + string.digits + "._-+@%#="

def _rand_name(r: random.Random, min_len: int = 1, max_len: int = 12) -> str:
    n = r.randint(min_len, max_len)
    # Avoid names that are purely dots unless intended
    s = ''.join(r.choice(SAFE_CHARS) for _ in range(n))
    # Occasionally produce hidden file (leading dot)
    if r.random() < 0.2:
        s = "." + s
    return s

def _rand_component(r: random.Random) -> str:
    pick = r.random()
    if pick < 0.12:
        return "."
    if pick < 0.24:
        return ".."
    if pick < 0.30:
        # empty component to exercise // and duplicate slashes
        return ""
    return _rand_name(r)

def _build_relative(r: random.Random, max_len: int) -> str:
    # Sometimes produce edge relatives directly
    edge = [".", "..", "./", "../", "./.", "../..", "./../", "..//./"]
    if r.random() < 0.2:
        rel = r.choice(edge)
    else:
        parts: List[str] = []
        depth = r.randint(1, 6)
        for _ in range(depth):
            parts.append(_rand_component(r))
        # Join allowing empty components to yield double slashes
        rel = "/".join(parts)
        # Occasionally prefix ./ or ../
        if r.random() < 0.35:
            rel = ("./" if r.random() < 0.6 else "../") + rel
    # Optionally add trailing slash
    if r.random() < 0.3 and not rel.endswith("/"):
        rel += "/"
    if len(rel) > max_len:
        rel = rel[:max_len]
    # Ensure not absolute
    while rel.startswith('/'):
        rel = rel[1:]
    if rel == "":
        rel = "."
    return rel

def _build_absolute(r: random.Random, max_len: int, prefer_short: bool = False) -> str:
    # Start at root
    path = "/"
    # Sometimes just root
    if r.random() < 0.1:
        return path
    # Depth and component length tuned by prefer_short
    depth = r.randint(1, 6 if not prefer_short else 3)
    for _ in range(depth):
        comp = _rand_component(r)
        if comp == "" and path.endswith("/"):
            # already produces double slash; keep as is
            pass
        if not path.endswith("/"):
            path += "/"
        path += comp
        if len(path) >= max_len:
            path = path[:max_len]
            break
    # Collapse accidental leading // occasionally left as-is to exercise normalization
    if r.random() < 0.3:
        # Add extra slashes to exercise dedup
        path = path.replace("/", "//")
    # Optionally add trailing slash
    if r.random() < 0.35 and not path.endswith("/"):
        path += "/"
    # Ensure starts with '/'
    if not path.startswith('/'):
        path = "/" + path
    # Trim to limit
    if len(path) > max_len:
        path = path[:max_len]
    return path

def _maybe_socket_friendly(r: random.Random, p: str) -> str:
    # UNIX domain socket path length limit: typical sun_path is 108 bytes.
    # Sometimes ensure the path fits comfortably.
    if r.random() < 0.55:
        limit = r.choice([80, 100, 104, 108])
        if len(p) > limit:
            # Trim safely at component boundary if possible
            if '/' in p[:limit]:
                cut = p.rfind('/', 0, limit)
                if cut > 0:
                    p = p[:cut]
            p = p[:limit]
            # Avoid empty
            if p == "":
                p = "/tmp"
    return p

def _compose_multiple_paths_blob(r: random.Random) -> bytes:
    # Compose several paths separated by newlines to increase coverage for FUZZ_PARAM_STR usage
    lines: List[str] = []
    count = r.randint(1, 5)
    for _ in range(count):
        if r.random() < 0.6:
            p = _build_absolute(r, max_len=300, prefer_short=r.random() < 0.7)
            p = _maybe_socket_friendly(r, p)
        else:
            p = _build_relative(r, max_len=200)
        lines.append(p)
    blob = "\n".join(lines)
    # Ensure non-empty and <= 4096
    b = blob.encode('utf-8', 'ignore')
    if len(b) > 4096:
        b = b[:4096]
    if not b:
        b = b"/"
    return b

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    mode = r.random()
    if mode < 0.2:
        # Single absolute path, short socket-friendly
        p = _build_absolute(r, max_len=200, prefer_short=True)
        p = _maybe_socket_friendly(r, p)
        return p.encode('utf-8', 'ignore')
    elif mode < 0.4:
        # Single relative path with dot segments
        p = _build_relative(r, max_len=256)
        return p.encode('utf-8', 'ignore')
    elif mode < 0.6:
        # Absolute path with a few ../ and // sprinkled to stress normalization
        base = _build_absolute(r, max_len=300, prefer_short=False)
        # Inject segments
        segs = base.split('/')
        if r.random() < 0.7:
            insert_pos = r.randint(1, max(1, len(segs)-1))
            segs[insert_pos:insert_pos] = ["..", ".", ""]
        p = "/".join(segs)
        p = _maybe_socket_friendly(r, p)
        return p.encode('utf-8', 'ignore')
    elif mode < 0.8:
        # Mix of paths in one buffer (newline-separated)
        return _compose_multiple_paths_blob(r)
    else:
        # Edge cases and tiny forms
        choices = ["/", ".", "..", "./", "../", "/./", "/../", "/tmp/", "/var/run/nagios.sock", "/tmp/.s-" + _rand_name(r,1,6)]
        p = r.choice(choices)
        return p.encode('utf-8', 'ignore')
